/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>
/// true, if exception should be thrown; otherwise, false.
/// </returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// Retrieves the order parameters record.
/// </summary>
/// <returns>
/// The order parameters record.
/// </returns>
public static SOrderParameters find()
{
    SOrderParameters parameters;

    select firstOnly parameters;

    return parameters;
}

/// <summary>
/// Returns the number sequence reference for Order ID.
/// </summary>
/// <returns>
/// The Order ID number sequence reference.
/// </returns>
public static NumberSequenceReference numRefOrderId()
{
    return NumberSeqReference::findReference(
        extendedTypeNum(SOrderID));
}
